UPDATE `quest_template_locale` SET `Details` = 'Rapporter la Peau intacte d''Ouro, 2 Idoles du sage, 5 Scarabées d''argent et 5 Scarabées d''os à Kandrostrasz, à l''intérieur d''Ahn''Qiraj. Pour terminer cette quête, il faut aussi que la Progéniture de Nozdormu soit au moins Amicale à votre égard.', `VerifiedBuild` = 0 WHERE `locale` = 'frFR' AND `ID` = 8631;
