UPDATE `quest_template_locale` SET `Details` = 'Donnez votre Coiffe de bestiaire et votre Tunique de bestiaire à Deliana.', `VerifiedBuild` = 0 WHERE `locale` = 'frFR' AND `ID` = 9000;
