UPDATE `quest_template_locale` SET `Details` = 'Prendre le Surplomb, le Stade et la Colline brisée, puis retourner voir l''adjudante Tracy Fièrepuits au bastion de l''Honneur dans la péninsule des Flammes infernales.', `VerifiedBuild` = 0 WHERE `locale` = 'frFR' AND `ID` = 13410;
