UPDATE `quest_template_locale` SET `Details` = 'Récupérez un peu de Pain des morts, et donnez-le à l''Esprit de Clairvoyant joyeux dans le cimetière de Shattrath.$b$bUtilisez un Chrysanthème orange pour voir l’esprit, qui sinon restera invisible.', `VerifiedBuild` = 0 WHERE `locale` = 'frFR' AND `ID` = 14173;
